// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address caller, address to, uint256 depositAmount, uint256 migrateAmount) public {
        vm.assume(caller != address(0));
        vm.assume(to != address(0));
        vm.assume(depositAmount > 0);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        uint256 balBefore = address(c).balance;
        vm.prank(caller);
        try c.migrateTo(to) {} catch {}
        uint256 balAfter = address(c).balance;
        address creatorAddress = address(this);
        assertTrue(balBefore == balAfter || caller == creatorAddress);
    }
}
